/**
 * Feature: backgrounds.
 * Pre-installed looks for slides, in two kinds:
 *
 * Still backgrounds are pure CSS (gradients and conic rays), so they
 * ship inside the app on every machine with zero files to lose.
 *
 * Motion backgrounds are short looping videos generated by
 * assets/backgrounds/generate.py (see docs/backgrounds.md). They live
 * under public/backgrounds/ and each one falls back to its CSS look
 * when the video file is missing, so a fresh clone never shows a
 * broken slide. Video paths are relative, not absolute, so they also
 * work when the packaged app loads over file:// instead of a server.
 */

export type BackgroundPreset = {
  id: string
  name: string
  kind: 'still' | 'video'
  /** CSS background, always rendered underneath (and alone for stills). */
  css: string
  /** Relative path to the looping video, for motion presets. */
  video?: string
}

